select exists (select 1 from information_schema.columns where table_schema='public' and table_name='assignment_submissions' and column_name='late') and exists (select 1 from pg_trigger where tgname='assignment_submission_late' and not tgisinternal) and exists (select 1 from pg_constraint where conname='assignment_submissions_assignment_student_key') as ok, exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='submissions_student_delete_orphan') as storage_ok;
